import{_ as o,l as i,o as r,c as s,v as E,p as d,x as n,d as e,i as p,S as u,b as t}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"私募与中性策略","description":"","frontmatter":{"title":"私募与中性策略","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-private-neutral.md","filePath":"quant/cn-private-neutral.md","lastUpdated":1789023840000}'),B={name:"quant/cn-private-neutral.md"};function h(c,a,A,m,f,b){const l=i("Mermaid");return r(),s("div",null,[a[1]||(a[1]=E('<h1 id="私募与中性策略" tabindex="-1">私募与中性策略 <a class="header-anchor" href="#私募与中性策略" aria-label="Permalink to &quot;私募与中性策略&quot;">​</a></h1><div class="epigraph"><p>市场中性要求空头腿真实存在。A 股空头主要是股指期货与有限的融券；贴水、保证金与政策会把「中性」写成时变的净暴露。</p><footer>—— 对照《私募证券投资基金运作指引》对杠杆、流动性与程序化的要求；中金所股指期货合约与结算细则；[做空约束](/quant/cn-short-constraint)</footer></div><p><a href="/quant/cn-public-quant">上一课</a>把公募钉在跟踪误差。本课的缺口是<strong>私募证券产品</strong>：可更高换手、可用期货对冲，但受协会运作指引、会员保证金与空头供给约束。中性不是收益的统计性质，是头寸结构。后课把融券与转融通单独写细；本课先给产品层的对冲会计。<a href="/quant/cn-amac-program-trading">中基协程序化</a> 是叠加层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票多头 \\(L\\) 加股指期货空头 \\(H\\)，净值收益 \\(\\approx L-H\\) 的 beta 近零当且仅当 \\(H\\) 的标的、乘数、保证金与基差与 \\(L\\) 匹配。IC/IM 对中小盘、IF/IH 对大盘，用错合约会留下市值敞口。贴水变深时空头腿盈利、现货相对基准的超额被掩盖或夸大——归因必须拆：选股超额、基差、保证金成本。问题是把中性定义成「对可复制基准的净暴露在限额内」，而不是「多空名义相等」。</p><p>杠杆：期货保证金使名义暴露可以数倍于净值。运作指引对杠杆、流动性、集中度有要求；程序化要报告。2015 年后保证金、平今、限仓多次调整，历史回测必须分段。把 2014 年的杠杆假设用到 2016 年，产品不可复制。</p><h3 id="融券中性与期货中性不是同一产品" tabindex="-1">融券中性与期货中性不是同一产品 <a class="header-anchor" href="#融券中性与期货中性不是同一产品" aria-label="Permalink to &quot;融券中性与期货中性不是同一产品&quot;">​</a></h3><p>个股融券能对冲特异风险，但标的、费率、召回与 2024 年转融券暂停使个股空头腿极窄，见下一课。多数「市场中性」是期货对冲的指数中性或行业不完全中性。行业中性在空头不可得时退化成低配，<a href="/quant/cn-short-constraint">短约束课</a>已写。本课要求产品说明书与回测使用同一名称：期货中性 / 有限融券中性，不要都叫 market neutral。</p><p><span class="marginnote">T+1 使多头腿当日不能卖。期货可平今（费率随时点而变）。对冲可以在当日调整 beta，个股特异风险与涨跌停缺腿仍在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>账本分列：现货超额、期货基差与展期、借券费、保证金利息、跟踪误差相对对冲指数。压力：贴水再扩大 \\(x\\) 点、保证金上调、涨跌停导致现货不可卖而期货仍结算。容量：期货持仓限额与市场深度可能先于股票 ADV 耗尽；拥挤时贴水是价格信号。与公募指增对照：私募可以主动管理净暴露，但净暴露一旦常驻，产品就变成带杠杆的指数择时，应改名。</p><p>程序化与高频认定：中性策略的报撤若靠期货腿完成，股票腿仍受股票程序化规则。不要假设「对冲在期货所就可以在股票上任意报撤」。</p><h3 id="估值与净值" tabindex="-1">估值与净值 <a class="header-anchor" href="#估值与净值" aria-label="Permalink to &quot;估值与净值&quot;">​</a></h3><p>开放式私募净值用估值政策：停牌股、涨跌停、期货结算价。投资者赎回发生在净值上，策略风险发生在可成交价上。两者差是流动性错配，运作指引关注的对象。回测若用收盘价对停牌股连续计价，赎回压力会被低估。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空头工具短缺时，对冲需求挤在期货，贴水是均衡不是错误。中性产品卖的是选股残差，买的是基差风险与政策风险。2015、2017、2023–24 的规则变化证明残差的方差有制度分量。工程课的 CCP 与保证金路径在这里变成产品爆仓路径：VM 抽现金时，名义中性仍可能强制减仓。</p><p>多策略私募里，中性、指增、CTA 共用保证金。归因必须分簿，否则 CTA 的趋势会算进中性 alpha。</p>',17)),(r(),d(u,null,{default:n(()=>[p(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Long%5B%22%E8%82%A1%E7%A5%A8%E5%A4%9A%E5%A4%B4%20T%2B1%22%5D%20--%3E%20Port%5B%22%E7%BB%84%E5%90%88%E5%87%80%E5%80%BC%22%5D%0A%20%20Fut%5B%22%E8%82%A1%E6%8C%87%E6%9C%9F%E8%B4%A7%E7%A9%BA%E5%A4%B4%22%5D%20--%3E%20Port%0A%20%20Basis%5B%22%E8%B4%B4%E6%B0%B4%E4%B8%8E%E5%B1%95%E6%9C%9F%22%5D%20--%3E%20Attr%5B%22%E5%BD%92%E5%9B%A0%E6%8B%86%E5%88%86%22%5D%0A%20%20Port%20--%3E%20Attr%0A%20%20Margin%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8E%E9%99%90%E4%BB%93%22%5D%20--%3E%20Cap%5B%22%E4%BA%A7%E5%93%81%E5%AE%B9%E9%87%8F%22%5D%0A%20%20Lend%5B%22%E6%9C%89%E9%99%90%E8%9E%8D%E5%88%B8%22%5D%20--%3E%20Idio%5B%22%E7%89%B9%E5%BC%82%E5%AF%B9%E5%86%B2%20%E5%8F%AF%E9%80%89%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t("h2",{id:"边界",tabindex:"-1"},[e("边界 "),t("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=t("p",null,"不提供未备案产品、规避运作指引杠杆或分拆产品以逃避程序化报告的结构。收益互换把暴露转到经销商，成本与对手方风险仍在，须披露而非消失。本课不给出具体管理人排名。",-1)),a[4]||(a[4]=t("h2",{id:"小结",tabindex:"-1"},[e("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=t("ul",null,[t("li",null,"中性是对冲结构：期货中性与融券中性工具不同，须命名诚实。"),t("li",null,"归因拆选股、基差、保证金；压力用保证金上调与贴水变深。"),t("li",null,"制度分段回测；T+1 与涨跌停造成缺腿。"),t("li",null,"出处：中基协《私募证券投资基金运作指引》；中金所合约细则；本栏做空与期现课。")],-1))])}const x=o(B,[["render",h]]);export{P as __pageData,x as default};
